<section class="panel"><div class="panel-heading"><h2>Profile für diese Gruppe</h2><span class="subtle">Zuweisungen, keine vollständige Auswertung aller effektiven Rechte</span></div><?php foreach($data['profiles'] as$row): ?><article class="group-row profile-row"><div><h3><?= $e($row['profile']->label) ?> <span class="badge <?= $row['assigned']?'badge-active':'badge-neutral' ?>"><?= $row['assigned']?'Zugewiesen':'Nicht zugewiesen' ?></span></h3><p><?= $e($row['profile']->description) ?></p></div>
<?php if($row['available']): ?><form method="post" action="/permissions/change" class="settings-form"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="group" value="<?= $e($data['selected_group']['id']) ?>"><input type="hidden" name="space" value="<?= $e($data['selected_space']['id']??'') ?>"><input type="hidden" name="selection" value="<?= $e(json_encode([$row['profile']->id,$row['fingerprint']],JSON_THROW_ON_ERROR)) ?>"><input type="hidden" name="operation" value="<?= $row['assigned']?'revoke':'grant' ?>"><label class="checkbox-label"><input type="checkbox" name="confirm" value="1" required> <?= $e($row['profile']->label) ?> für <?= $e($data['selected_group']['name']) ?> <?= $row['assigned']?'entziehen':'zuweisen' ?></label><button class="button <?= $row['assigned']?'button-outline':'' ?>" type="submit"><?= $row['assigned']?'Profil entziehen':'Profil zuweisen' ?></button></form><?php else: ?><p class="notice notice-error">Dieses Profil ist wegen einer abweichenden vorhandenen Rollendefinition oder fehlender Pluginrechte gesperrt. Es wird nicht automatisch umgeschrieben.</p><?php endif ?></article><?php endforeach ?></section>
<?php endif ?>
